// Minimal stand-in for the Obsidian API, enough to exercise Study Zone's logic in Node.
let OFFSET = 0;
function moment(s) {
  const base = new Date('2026-01-01T12:00:00Z'); base.setUTCDate(base.getUTCDate() + OFFSET);
  return { d: s ? new Date(s + 'T12:00:00Z') : base,
    format() { return this.d.toISOString().slice(0, 10); },
    add(n) { this.d = new Date(this.d); this.d.setUTCDate(this.d.getUTCDate() + n); return this; },
    subtract(n) { return this.add(-n); } };
}
class TFile { constructor(path) { this.path = path; this.basename = path.split('/').pop().replace(/\.md$/, ''); this.extension = 'md';
  const dir = path.split('/').slice(0, -1).join('/'); this.parent = { path: dir, name: dir.split('/').pop() || '' }; } }
class Base { constructor(app) { this.app = app; } registerEvent() {} registerInterval() {} }
module.exports = { Plugin: Base, ItemView: Base, Modal: Base, Notice: class {}, Setting: Base, PluginSettingTab: Base,
  MarkdownRenderer: {}, TFile, moment, normalizePath: (p) => p.replace(/\/+$/, ''), __setDay: (n) => (OFFSET = n) };
